import random


def generate(seed: int = 0) -> list[str]:
    """Cases are palindromes or a palindrome with one value changed; list values stay in range."""
    r = random.Random(seed)
    cases = [[1], [1, 2], [1, 2, 2, 1]]
    seen = {tuple(x) for x in cases}
    while len(cases) < 600:
        n = r.randint(1, 100)
        half = [r.randint(0, 9) for _ in range((n + 1) // 2)]
        a = half + half[: n // 2][::-1]
        if r.randrange(2) and n:
            i = r.randrange(n)
            a[i] = (a[i] + 1) % 10
        key = tuple(a)
        if key not in seen:
            seen.add(key)
            cases.append(a)
    return [f"candidate(head=list_node({a!r}))" for a in cases]


